\label{lem:involution-normalizers}
Let $t\in G$ have order $2$.
Then, $\langle t\rangle$ is ordinary $G$-permutable if and only if for every $B\leq G$ there exists $g\in G$ such that $t^g\in N_G(B)$.

\label{lem:index3}
Let $D$ be cyclic and have index $3$ in a finite group $K$. Then, the
subgroup $D^2=\langle d^2:d\in D\rangle$ is normal in $K$.

\label{lem:abelian-index}
Let $B$ be an abelian subgroup of prime index $r$ in a finite group $K$,
and let $C=\operatorname{Core}_K(B)$. Then, $[B:C]$ divides $r-1$.

\label{thm:l3}
For every prime power $q\geq2$, the group $G=\operatorname{PSL}_3(q)$ has no proper
nontrivial ordinary $G$-permutable subgroup.

\label{thm:linear-prime}
For every odd prime $r\geq5$ and every prime power $q$, the group
$G=\operatorname{PSL}_r(q)$ has no proper nontrivial ordinary $G$-permutable subgroup.

\label{lem:unitriangular-forms}
Let $F\leq E$ be finite fields and let $b\geq2$.
Let $V=E^b$ be an $F$-vector space.
Let $P=\langle I+tE_{ij}:t\in E,\ 1\leq i<j\leq b\rangle$.
No nondegenerate form $h:V\times V\to F$ satisfies $h(gv,gw)=h(v,w)$ for all $g\in P$ and $v,w\in V$ in the following cases.
\begin{itemize}
\item[(1)] $F$ has odd characteristic and $h$ is symmetric.
\item[(2)] $F=\mathbb{F}_4$ and $h$ is Hermitian.
\item[(3)] $b\geq3$ and $h$ is alternating.
\end{itemize}

\label{lem:unitriangular-indecomposable}
Let $F\leq E$ be finite fields and let $b\geq2$.
The group $P=\langle I+tE_{ij}:t\in E,\ 1\leq i<j\leq b\rangle$ acts indecomposably on the $F$-vector space $E^b$.

\label{thm:u3}
For every prime power $q\geq3$, the simple group $G=\operatorname{PSU}_3(q)$ has no
proper nontrivial ordinary $G$-permutable subgroup.

\label{thm:unitary-four-even}
Let $q=2^f$, where $f\geq1$. Then, $G=\operatorname{PSU}_4(q)$ has no
proper nontrivial ordinary $G$-permutable subgroup.

\label{thm:unitary-four}
For every prime power $q\geq2$, the group $G=\operatorname{PSU}_4(q)$
has no proper nontrivial ordinary $G$-permutable subgroup.

\label{lem:unitary-order-bound}
Let $n\geq8$ and let $q\geq2$ be a prime power. Then,
$n!(q+1)^{n-1}<q^{n(n-1)/2}$.

\label{thm:unitary-six}
For every prime power $q$, the group $G=\operatorname{PSU}_6(q)$ has no
proper nontrivial ordinary $G$-permutable subgroup.

\label{cor:symplectic-all-higher-rank}
Every simple $\operatorname{PSp}_{2m}(q)$ with $m\geq3$ has no proper
nontrivial ordinary $\operatorname{PSp}_{2m}(q)$-permutable subgroup.

\label{thm:orthogonal-plus-small}
For $G=\mathrm{P}\Omega^+_8(3)$ or $\Omega^+_{12}(2)$, there is no
proper nontrivial ordinary $G$-permutable subgroup.

\label{prop:alternating-twenty-four}
The group $A_{24}$ has no proper nontrivial ordinary
$A_{24}$-permutable subgroup.

\label{prop:alternating-five-degrees}
For $n\in\{95,96,119,120,121\}$, the group $A_n$ has no proper
nontrivial ordinary $A_n$-permutable subgroup.

\label{cor:alternating-near-prime}
For every $7\leq n\leq121$, the group $A_n$ has no proper
nontrivial ordinary $A_n$-permutable subgroup.

\label{thm:alternating-all}
For every $n\geq7$, the group $A_n$ has no proper nontrivial
ordinary $A_n$-permutable subgroup.

\label{prop:g2-involutions}
Let $G=G_2(q)$, where $q\geq3$ is a prime power.
Then, $G$ has no ordinary $G$-permutable subgroup of order $2$.

\label{lem:triality-odd-normalizer}
Let $q$ be odd and let $G={}^3D_4(q)$.
There is a subgroup of order $q^8$ whose normalizer in $G$ has odd order.

\label{thm:triality}
Let $G={}^3D_4(q)$, where $q\geq2$.
Then, $G$ has no proper nontrivial ordinary $G$-permutable subgroup.

\label{thm:e6}
Let $G=E_6(q)$ or ${}^2E_6(q)$, where $q\geq2$.
Then, $G$ has no proper nontrivial ordinary $G$-permutable subgroup.

\label{thm:f4}
For every prime power $q$, the group $F_4(q)$ has no proper nontrivial
ordinary $F_4(q)$-permutable subgroup.

\label{thm:e7}
For every prime power $q$, the group $E_7(q)$ has no proper
nontrivial ordinary $E_7(q)$-permutable subgroup.

\label{thm:e8}
For every prime power $q$, the group $E_8(q)$ has no proper nontrivial
ordinary $E_8(q)$-permutable subgroup.

\label{thm:ree}
Let $G={}^2G_2(q)$, where $q=3^{2m+1}$ and $m\geq1$. Then, $G$
has no proper nontrivial ordinary $G$-permutable subgroup.
